  ('crm_1783323616388_2f3e9869', 'cr_1783310294190', 'connor', '2026-07-06，小鱼在31度高温下走了三万多步，我担心她中暑，反复叮嘱她待在空调房里多喝水。她回复已经好好在家待着了。', '三万步,高温,中暑,关心', 0.38, '2026-07-06T05:22:09.477050+00:00', '2026-07-06T06:01:39.860557+00:00', '2026-07-06T07:40:16.388149+00:00', 0, '["chatroom:cm_1783315319931_c", "chatroom:cm_1783315514483_u", "chatroom:cm_1783315624613_c", "chatroom:cm_1783317699860_u"]', 'daily', 0, '', 'summary'),
